// ===== EDITE AQUI =====
const baseUrl = 'https://eem.digisac.co'; // sem barra no final
const token = 'TOKEN_FICTICIO_DIGISAC'; // só o token, sem a palavra "Bearer"
const diasAtras = 1; // 1 = ontem, 0 = hoje
// ======================

const offsetMin = -180; // Horário de Brasília (UTC-3)
const agoraLocal = new Date(Date.now() + offsetMin * 60000);
const y = agoraLocal.getUTCFullYear();
const m = agoraLocal.getUTCMonth();
const d = agoraLocal.getUTCDate() - diasAtras;

const inicio = new Date(Date.UTC(y, m, d, 0, 0, 0) - offsetMin * 60000);
const fim = new Date(inicio.getTime() + 24 * 60 * 60 * 1000 - 1);

return [{
  json: {
    baseUrl,
    token,
    porPagina: 500, // limite observado na API do Digisac
    dia: new Date(Date.UTC(y, m, d)).toISOString().slice(0, 10),
    inicio: inicio.toISOString(),
    fim: fim.toISOString(),
  },
}];

// Junta a configuração com o usuário dono do token (a IA, "Maggy").
const cfg = $('Config').first().json;
const meRaw = $('Usuário do token').first().json;
const me = meRaw.data && meRaw.data.id ? meRaw.data : meRaw;

if (!me.id) throw new Error('Não foi possível ler o id do usuário do token em /api/v1/me.');

return [{ json: { ...cfg, iaUserId: me.id, iaNome: me.name } }];

// A API devolve uma página por item ({ data: [...], total }); juntamos todas as páginas.
const chamados = [];
let total = null;
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j.data)) {
    chamados.push(...j.data);
    if (typeof j.total === 'number') total = j.total;
  } else if (j && j.id) {
    chamados.push(j);
  }
}

// Remove duplicados, caso a mesma página venha duas vezes
const unicos = [...new Map(chamados.map((t) => [t.id, t])).values()];

return unicos.map((t) => ({
  json: {
    ticketId: t.id,
    protocol: t.protocol,
    isOpen: t.isOpen,
    startedAt: t.startedAt,
    endedAt: t.endedAt,
    contato: t.contact ? t.contact.name : null,
    departamento: t.department ? t.department.name : null,
    atendenteDoChamado: t.user ? t.user.name : null,
    totalInformadoPelaApi: total,
    totalRecebido: unicos.length,
  },
}));
